```json
{
  "manifest_version": 2,
  "name": "Amazon Price Generator",
  "version": "1.0",
  "description": "A Chrome extension that generates prices for your online store based on user data",
  "permissions": ["activeTab", "https://www.amazon.com/*"],
  "content_scripts": [
    {
      "matches": ["https://www.amazon.com/*"],
      "js": ["contentScript.js"]
    }
  ],
  "background": {
    "scripts": ["background.js"],
    "persistent": false
  },
  "browser_action": {
    "default_popup": "popup.html"
  }
}
```
